    print("GET credential:", http("GET", "http://127.0.0.1:8962/v1/credentials/vc_old")[0])
    st, r = http("POST", "http://127.0.0.1:8962/v1/credentials/vc_old/present",
                 {"disclose": ["/role"]})
    print("旧凭证 present:", st, r)
finally:
    proc.terminate()
